object.Translations:
__userInfo = 'The user is a customer of ABC Bank.';
__companyInformation = 'ABC Bank is open 24 hours every day and provides a wide range of banking services including checking and savings accounts, personal and business loans, credit cards, and online banking.';
__knowledge = "- Account Management: Customers can open or close checking and savings accounts online or at any branch. - Loan Information: Personal, auto, and mortgage loans are available.";

