object.PropertiesDefinition:
[
    {
        "name": "__userInfo",
        "title": "Information about the user",
        "hint": "All the information the bot needs to know about the user. This can include why they are calling, the phone number they are calling from (for a voicebot), or other specific details stored in variables, such as their name, their particular situation, the amount of money they owe, etc. Character limit: 1,000 characters.",
        "controlSettings": {
            "controlType": "text",
            "maxLength": 1000,
            "dataType": "string",
            "rows": 2,
            "readonly": false
        }
    },
    {
        "name": "__companyInformation",
        "title": "Company information",
        "hint": "Any information related to the company the bot represents, such as the services it provides. Character limit: 10,000 characters. ",
        "controlSettings": {
            "controlType": "text",
            "maxLength": 9999,
            "dataType": "string",
            "rows": 10,
            "readonly": false
        }
    },
    {
        "name": "__knowledge",
        "title": "General knowledge",
        "hint": "Any information that the bot should be able to answer immediately about the topic at hand. Character limit: 10,000 characters. For larger amounts of information, create a separate knowledge base and use the RAG Search Component (see OmniAgent Academy).",
        "controlSettings": {
            "controlType": "text",
            "maxLength": 9999,
            "dataType": "string",
            "rows": 10,
            "readonly": false
        }
    }
]

